/**
 * IndexedDB storage backend for browser persistence
 */

import type { CacheEntry } from "../core/types.js";
import type { StorageBackend, EntryMetadata } from "./storage-interface.js";
import { isExpired } from "../strategies/ttl-manager.js";
import { filterByPattern } from "../utils/pattern.js";

export interface IndexedDBStorageConfig {
  name: string;
  version?: number;
}

interface IndexedDBEntry<T> {
  key: string;
  value: T;
  metadata: EntryMetadata;
}

interface TagEntry {
  tag: string;
  keys: string[];
}

/**
 * IndexedDB storage implementation
 */
export class IndexedDBStorage<T = any> implements StorageBackend<T> {
  private dbName: string;
  private version: number;
  private db: IDBDatabase | null = null;
  private initPromise: Promise<void> | null = null;

  constructor(config: IndexedDBStorageConfig) {
    this.dbName = `cachefn-${config.name}`;
    this.version = config.version ?? 1;
  }

  /**
   * Initialize the IndexedDB database
   */
  private async init(): Promise<void> {
    if (this.db) {
      return;
    }

    if (this.initPromise) {
      return this.initPromise;
    }

    this.initPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.version);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Create entries store
        if (!db.objectStoreNames.contains("entries")) {
          const entriesStore = db.createObjectStore("entries", {
            keyPath: "key",
          });
          entriesStore.createIndex("expiresAt", "metadata.expiresAt", {
            unique: false,
          });
        }

        // Create tags store
        if (!db.objectStoreNames.contains("tags")) {
          db.createObjectStore("tags", { keyPath: "tag" });
        }
      };
    });

    return this.initPromise;
  }

  async get(key: string): Promise<T | undefined> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readwrite");
      const store = transaction.objectStore("entries");
      const request = store.get(key);

      request.onsuccess = async () => {
        const entry: IndexedDBEntry<T> | undefined = request.result;

        if (!entry) {
          resolve(undefined);
          return;
        }

        // Check if expired
        const cacheEntry: CacheEntry<T> = {
          key: entry.key,
          value: entry.value,
          ...entry.metadata,
        };

        if (isExpired(cacheEntry)) {
          await this.delete(key);
          resolve(undefined);
          return;
        }

        // Update access metadata
        entry.metadata.hits++;
        entry.metadata.lastAccess = Date.now();
        store.put(entry);

        resolve(entry.value);
      };

      request.onerror = () => reject(request.error);
    });
  }

  async set(key: string, value: T, metadata: EntryMetadata): Promise<void> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(
        ["entries", "tags"],
        "readwrite"
      );
      const entriesStore = transaction.objectStore("entries");
      const tagsStore = transaction.objectStore("tags");

      // Get old entry to clean up old tags
      const getRequest = entriesStore.get(key);

      getRequest.onsuccess = async () => {
        const oldEntry: IndexedDBEntry<T> | undefined = getRequest.result;

        // Remove old tags
        if (oldEntry?.metadata.tags) {
          for (const tag of oldEntry.metadata.tags) {
            await this.removeTagFromStore(tagsStore, tag, key);
          }
        }

        // Set new entry
        const entry: IndexedDBEntry<T> = { key, value, metadata };
        entriesStore.put(entry);

        // Add new tags
        if (metadata.tags) {
          for (const tag of metadata.tags) {
            await this.addTagToStore(tagsStore, tag, key);
          }
        }
      };

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  async has(key: string): Promise<boolean> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readonly");
      const store = transaction.objectStore("entries");
      const request = store.get(key);

      request.onsuccess = async () => {
        const entry: IndexedDBEntry<T> | undefined = request.result;

        if (!entry) {
          resolve(false);
          return;
        }

        const cacheEntry: CacheEntry<T> = {
          key: entry.key,
          value: entry.value,
          ...entry.metadata,
        };

        if (isExpired(cacheEntry)) {
          await this.delete(key);
          resolve(false);
          return;
        }

        resolve(true);
      };

      request.onerror = () => reject(request.error);
    });
  }

  async delete(key: string): Promise<boolean> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(
        ["entries", "tags"],
        "readwrite"
      );
      const entriesStore = transaction.objectStore("entries");
      const tagsStore = transaction.objectStore("tags");

      const getRequest = entriesStore.get(key);

      getRequest.onsuccess = async () => {
        const entry: IndexedDBEntry<T> | undefined = getRequest.result;

        if (!entry) {
          resolve(false);
          return;
        }

        // Remove from entries
        entriesStore.delete(key);

        // Remove from tags
        if (entry.metadata.tags) {
          for (const tag of entry.metadata.tags) {
            await this.removeTagFromStore(tagsStore, tag, key);
          }
        }

        resolve(true);
      };

      transaction.onerror = () => reject(transaction.error);
    });
  }

  async clear(): Promise<void> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(
        ["entries", "tags"],
        "readwrite"
      );

      transaction.objectStore("entries").clear();
      transaction.objectStore("tags").clear();

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  async keys(pattern?: string): Promise<string[]> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readonly");
      const store = transaction.objectStore("entries");
      const request = store.getAllKeys();

      request.onsuccess = () => {
        const allKeys = request.result as string[];
        resolve(filterByPattern(allKeys, pattern));
      };

      request.onerror = () => reject(request.error);
    });
  }

  async size(): Promise<number> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readonly");
      const store = transaction.objectStore("entries");
      const request = store.count();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async getKeysByTag(tag: string): Promise<string[]> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["tags"], "readonly");
      const store = transaction.objectStore("tags");
      const request = store.get(tag);

      request.onsuccess = () => {
        const entry: TagEntry | undefined = request.result;
        resolve(entry?.keys ?? []);
      };

      request.onerror = () => reject(request.error);
    });
  }

  async addTag(tag: string, key: string): Promise<void> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["tags"], "readwrite");
      const store = transaction.objectStore("tags");

      this.addTagToStore(store, tag, key);

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  async removeTag(tag: string, key: string): Promise<void> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["tags"], "readwrite");
      const store = transaction.objectStore("tags");

      this.removeTagFromStore(store, tag, key);

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  async getTagsForKey(key: string): Promise<string[]> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readonly");
      const store = transaction.objectStore("entries");
      const request = store.get(key);

      request.onsuccess = () => {
        const entry: IndexedDBEntry<T> | undefined = request.result;
        resolve(entry?.metadata.tags ?? []);
      };

      request.onerror = () => reject(request.error);
    });
  }

  async getMetadata(key: string): Promise<EntryMetadata | undefined> {
    await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(["entries"], "readonly");
      const store = transaction.objectStore("entries");
      const request = store.get(key);

      request.onsuccess = () => {
        const entry: IndexedDBEntry<T> | undefined = request.result;

        if (!entry) {
          resolve(undefined);
          return;
        }

        const cacheEntry: CacheEntry<T> = {
          key: entry.key,
          value: entry.value,
          ...entry.metadata,
        };

        if (isExpired(cacheEntry)) {
          this.delete(key);
          resolve(undefined);
          return;
        }

        resolve(entry.metadata);
      };

      request.onerror = () => reject(request.error);
    });
  }

  /**
   * Add a tag to the tag store
   */
  private async addTagToStore(
    store: IDBObjectStore,
    tag: string,
    key: string
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const getRequest = store.get(tag);

      getRequest.onsuccess = () => {
        const entry: TagEntry | undefined = getRequest.result;
        const keys = entry?.keys ?? [];

        if (!keys.includes(key)) {
          keys.push(key);
        }

        store.put({ tag, keys });
        resolve();
      };

      getRequest.onerror = () => reject(getRequest.error);
    });
  }

  /**
   * Remove a tag from the tag store
   */
  private async removeTagFromStore(
    store: IDBObjectStore,
    tag: string,
    key: string
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const getRequest = store.get(tag);

      getRequest.onsuccess = () => {
        const entry: TagEntry | undefined = getRequest.result;

        if (!entry) {
          resolve();
          return;
        }

        const keys = entry.keys.filter((k) => k !== key);

        if (keys.length === 0) {
          store.delete(tag);
        } else {
          store.put({ tag, keys });
        }

        resolve();
      };

      getRequest.onerror = () => reject(getRequest.error);
    });
  }
}
/**
 * Main CacheFn class
 */

import type {
  CacheFnConfig,
  SetOptions,
  CacheStats,
  StorageType,
  EventHandler,
} from "./types.js";
import type { StorageBackend } from "../storage/storage-interface.js";
import { MemoryStorage } from "../storage/memory-storage.js";
import { IndexedDBStorage } from "../storage/indexeddb-storage.js";
import { EventEmitter } from "./events.js";
import { StatsTracker } from "../analytics/stats.js";
import { calculateExpiration } from "../strategies/ttl-manager.js";
import { filterByPattern } from "../utils/pattern.js";

/**
 * CacheFn - Self-hosted caching solution
 */
export class CacheFn<T = any> {
  private storage: StorageBackend<T>;
  private events: EventEmitter;
  private stats: StatsTracker;
  private defaultTTL?: number;
  private namespace?: string;

  constructor(config: CacheFnConfig) {
    this.defaultTTL = config.defaultTTL;
    this.namespace = config.namespace;
    this.events = new EventEmitter();
    this.stats = new StatsTracker();

    // Initialize storage backend
    const storageType = config.storage ?? "memory";
    this.storage = this.createStorage(storageType, config);
  }

  /**
   * Get a value from cache
   */
  async get(key: string): Promise<T | undefined> {
    const fullKey = this.getFullKey(key);
    const startTime = performance.now();

    const value = await this.storage.get(fullKey);
    const accessTime = performance.now() - startTime;

    if (value !== undefined) {
      this.stats.recordHit();
      this.events.emit("hit", { key: fullKey, accessTime });
    } else {
      this.stats.recordMiss();
      this.events.emit("miss", { key: fullKey });
    }

    return value;
  }

  /**
   * Set a value in cache
   */
  async set(key: string, value: T, options?: SetOptions): Promise<void> {
    const fullKey = this.getFullKey(key);
    const ttl = options?.ttl ?? this.defaultTTL;

    const metadata = {
      createdAt: Date.now(),
      expiresAt: calculateExpiration(ttl),
      tags: options?.tags,
      hits: 0,
      lastAccess: Date.now(),
    };

    await this.storage.set(fullKey, value, metadata);

    this.stats.recordSet();
    this.events.emit("set", { key: fullKey, size: 1 });
  }

  /**
   * Check if a key exists in cache
   */
  async has(key: string): Promise<boolean> {
    const fullKey = this.getFullKey(key);
    return await this.storage.has(fullKey);
  }

  /**
   * Delete a value from cache
   */
  async delete(key: string): Promise<boolean> {
    const fullKey = this.getFullKey(key);
    const deleted = await this.storage.delete(fullKey);

    if (deleted) {
      this.stats.recordDelete();
      this.events.emit("delete", { key: fullKey });
    }

    return deleted;
  }

  /**
   * Clear all values from cache
   */
  async clear(): Promise<void> {
    if (this.namespace) {
      const keys = (await this.storage.keys()).filter((key) => this.ownsKey(key));
      await Promise.all(keys.map((key) => this.storage.delete(key)));
    } else {
      await this.storage.clear();
    }
    this.stats.reset();
  }

  /**
   * Get multiple values from cache
   */
  async getMany(keys: string[]): Promise<Array<T | undefined>> {
    return Promise.all(keys.map((key) => this.get(key)));
  }

  /**
   * Set multiple values in cache
   */
  async setMany(
    entries: Array<{ key: string; value: T; options?: SetOptions }>
  ): Promise<void> {
    await Promise.all(
      entries.map((entry) => this.set(entry.key, entry.value, entry.options))
    );
  }

  /**
   * Delete multiple values from cache
   */
  async deleteMany(keys: string[]): Promise<void> {
    await Promise.all(keys.map((key) => this.delete(key)));
  }

  /**
   * Get all keys matching a pattern
   */
  async keys(pattern?: string): Promise<string[]> {
    const allKeys = await this.storage.keys();

    // Remove namespace prefix if present
    const keysWithoutNamespace = allKeys.filter((key) => this.ownsKey(key)).map((key) =>
      this.namespace && key.startsWith(`${this.namespace}:`)
        ? key.slice(this.namespace.length + 1)
        : key
    );

    return filterByPattern(keysWithoutNamespace, pattern);
  }

  /**
   * Get the number of entries in cache
   */
  async size(): Promise<number> {
    return this.namespace ? (await this.keys()).length : await this.storage.size();
  }

  /**
   * Get or fetch a value (cache-aside pattern)
   */
  async getOrFetch(
    key: string,
    fetcher: () => Promise<T>,
    options?: SetOptions
  ): Promise<T> {
    const cached = await this.get(key);

    if (cached !== undefined) {
      return cached;
    }

    const value = await fetcher();
    await this.set(key, value, options);

    return value;
  }

  /**
   * Invalidate a single key (alias for delete)
   */
  async invalidate(key: string): Promise<boolean> {
    return await this.delete(key);
  }

  /**
   * Invalidate all keys with a specific tag
   */
  async invalidateByTag(tag: string): Promise<void> {
    const keys = (await this.storage.getKeysByTag(tag)).filter((key) => this.ownsKey(key));
    const count = keys.length;

    await Promise.all(keys.map((key) => this.storage.delete(key)));

    this.events.emit("invalidate", { pattern: `tag:${tag}`, count });
  }

  /**
   * Invalidate all keys with any of the specified tags
   */
  async invalidateByTags(tags: string[]): Promise<void> {
    await Promise.all(tags.map((tag) => this.invalidateByTag(tag)));
  }

  /**
   * Invalidate all keys matching a pattern
   */
  async invalidateByPattern(pattern: string | RegExp): Promise<void> {
    const allKeys = await this.keys();
    const matchingKeys = filterByPattern(allKeys, pattern);
    const count = matchingKeys.length;

    await Promise.all(matchingKeys.map((key) => this.delete(key)));

    const patternStr = pattern instanceof RegExp ? pattern.source : pattern;
    this.events.emit("invalidate", { pattern: patternStr, count });
  }

  /**
   * Touch a key to update its last access time
   */
  async touch(key: string): Promise<void> {
    const fullKey = this.getFullKey(key);
    const value = await this.storage.get(fullKey);

    if (value !== undefined) {
      const metadata = await this.storage.getMetadata(fullKey);
      if (metadata) {
        metadata.lastAccess = Date.now();
        await this.storage.set(fullKey, value, metadata);
      }
    }
  }

  /**
   * Get entries matching a pattern
   */
  async entries(options?: {
    pattern?: string;
    limit?: number;
  }): Promise<Array<{ key: string; value: T }>> {
    const keys = await this.keys(options?.pattern);
    const limitedKeys = options?.limit ? keys.slice(0, options.limit) : keys;

    const entries: Array<{ key: string; value: T }> = [];

    for (const key of limitedKeys) {
      const value = await this.get(key);
      if (value !== undefined) {
        entries.push({ key, value });
      }
    }

    return entries;
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<CacheStats> {
    const size = await this.size();

    // Get memory usage if using memory storage
    let memoryUsage: number | undefined;
    if (this.storage instanceof MemoryStorage) {
      memoryUsage = this.storage.getMemoryUsage();
    }

    return this.stats.getStats(size, memoryUsage);
  }

  /**
   * Register an event listener
   */
  on(event: string, handler: EventHandler): void {
    this.events.on(event, handler);
  }

  /**
   * Unregister an event listener
   */
  off(event: string, handler: EventHandler): void {
    this.events.off(event, handler);
  }

  /**
   * Get the full key with namespace
   */
  private ownsKey(key: string): boolean {
    return !this.namespace || key.startsWith(`${this.namespace}:`);
  }

  private getFullKey(key: string): string {
    return this.namespace ? `${this.namespace}:${key}` : key;
  }

  /**
   * Create storage backend based on type
   */
  private createStorage(
    type: StorageType,
    config: CacheFnConfig
  ): StorageBackend<T> {
    switch (type) {
      case "memory":
        return new MemoryStorage<T>({
          maxSize: config.maxSize,
          onEviction: (key, reason) => {
            this.stats.recordEviction();
            this.events.emit("eviction", { key, reason });
          },
        });

      case "indexeddb":
        return new IndexedDBStorage<T>({
          name: config.name,
        });

      default:
        throw new Error(`Unknown storage type: ${type}`);
    }
  }
}

